  date: string;
  slot: PickupSlot;
  kind: PickupAssigneeKind;
  guardianId: string | null;
  siblingChildId: string | null;
  playdateHostName: string | null;
  playdateLocation: string | null;
  playdateContactInfo: string | null;
  time: string | null;
  notes: string | null;
  assignedBy: string;
}

